"""Launch robot_state_publisher, joint_state_publisher and move_group for the arm3 robot.

All MoveIt parameters are assembled here directly (URDF/SRDF text + yaml config
files) instead of relying on an installed *_moveit_config package, since this
setup lives directly in a plain directory rather than a colcon workspace.
"""
import os
import yaml

from launch import LaunchDescription
from launch_ros.actions import Node

THIS_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.dirname(THIS_DIR)


def load_file(relative_path):
    with open(os.path.join(BASE_DIR, relative_path), "r") as f:
        return f.read()


def load_yaml(relative_path):
    with open(os.path.join(BASE_DIR, relative_path), "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    robot_description_content = load_file("urdf/arm3.urdf")
    robot_description_semantic_content = load_file("srdf/arm3.srdf")

    robot_description = {"robot_description": robot_description_content}
    robot_description_semantic = {
        "robot_description_semantic": robot_description_semantic_content
    }
    kinematics_yaml = load_yaml("config/kinematics.yaml")
    robot_description_kinematics = {"robot_description_kinematics": kinematics_yaml}

    joint_limits_yaml = load_yaml("config/joint_limits.yaml")
    robot_description_planning = {"robot_description_planning": joint_limits_yaml}

    ompl_yaml = load_yaml("config/ompl_planning.yaml")
    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_yaml,
    }

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_parameters = [
        robot_description,
        robot_description_semantic,
        robot_description_kinematics,
        robot_description_planning,
        planning_pipelines,
        planning_scene_monitor_parameters,
        {
            "allow_trajectory_execution": False,
            "publish_monitored_planning_scene": True,
        },
    ]

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        name="robot_state_publisher",
        output="log",
        parameters=[robot_description],
    )

    joint_state_publisher_node = Node(
        package="joint_state_publisher",
        executable="joint_state_publisher",
        name="joint_state_publisher",
        output="log",
        parameters=[robot_description],
    )

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        name="move_group",
        output="log",
        parameters=move_group_parameters,
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            joint_state_publisher_node,
            move_group_node,
        ]
    )

